export type GetProductsInput = { q: string }

export type GetProductsItem = { id: number; title: string; price: number; updatedAt?: string }

export type GetProductsResponse = { items: { id: number; title: string; price: number; updatedAt?: string }[] }

export async function getProducts(input: GetProductsInput, signal?: AbortSignal): Promise<GetProductsResponse> {
  const url = new URL("/api/products", "http://127.0.0.1:4177")
  url.searchParams.set("q", String(input.q))
  const response = await fetch(url, {
    method: "GET",
    signal,
    headers: {
      accept: 'application/json',
    },
  })
  if (!response.ok) {
    throw new Error("GET /api/products failed" + ` (${response.status})`)
  }
  return (await response.json()) as GetProductsResponse
}
